int cypress_probe(struct usb_serial_port *port)
{
    int ret;
    struct cypress_private *priv;

    /* Check for required endpoints */
    if (!port->port.open_count) {
        dev_err(&port->dev, "No endpoints found\n");
        return -ENODEV;
    }

    /* Allocate memory for private data structure */
    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    /* Initialize locks and FIFO buffers */
    spin_lock_init(&priv->lock);
    priv->read_fifo = usb_fifo_create(USB_FIFO_SIZE_DEFAULT);
    if (!priv->read_fifo) {
        ret = -ENOMEM;
        goto error_free_priv;
    }

    priv->write_fifo = usb_fifo_create(USB_FIFO_SIZE_DEFAULT);
    if (!priv->write_fifo) {
        ret = -ENOMEM;
        goto error_free_read_fifo;
    }

    /* Configure packet format based on interrupt output size */
    if (port->interrupt_out_size == 1)
        priv->packet_format = PACKET_FORMAT_1_BYTE;
    else if (port->interrupt_out_size == 2)
        priv->packet_format = PACKET_FORMAT_2_BYTE;
    else
        priv->packet_format = PACKET_FORMAT_DEFAULT;

    /* Handle special cases for certain devices */
    if (is_special_device(port->serial->dev)) {
        priv->special_case = true;
        priv->drain_delay = SPECIAL_CASE_DRAIN_DELAY;
    } else {
        priv->special_case = false;
        priv->drain_delay = DEFAULT_DRAIN_DELAY;
    }

    /* Set read/write intervals */
    if (port->read_interval == 0)
        port->read_interval = DEFAULT_READ_INTERVAL;

    if (port->write_interval == 0)
        port->write_interval = DEFAULT_WRITE_INTERVAL;

    /* Associate private data with the port */
    usb_set_serial_port_data(port, priv);

    return 0;

error_free_read_fifo:
    usb_fifo_free(priv->read_fifo);
error_free_priv:
    kfree(priv);
    return ret;
}

int cypress_probe(struct usb_serial_port *port)
{
    int ret = -ENOMEM;
    struct usb_serial *serial = port->serial;
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *bulk_out, *bulk_in;
    struct cypress_private *cypress;

    iface_desc = port->port->host->config->interface[0];
    bulk_out = usb_find_int_in_endpoint(iface_desc);
    bulk_in = usb_find_int_out_endpoint(iface_desc);
    if (!bulk_in || !bulk_out)
        return -ENODEV;

    cypress = kzalloc(sizeof(*cypress), GFP_KERNEL);
    if (!cypress)
        goto error;

    mutex_init(&cypress->lock);
    ret = usb_fill_bulk_urb(cypress->bulk_out_urb, serial->dev, bulk_out,
                            NULL, 0, cypress_read_bulk_callback, cypress);
    if (ret)
        goto error;

    ret = usb_fill_bulk_urb(cypress->bulk_in_urb, serial->dev, bulk_in,
                            NULL, 0, cypress_write_bulk_callback, cypress);
    if (ret)
        goto error;

    if (iface_desc->bNumEndpoints == 4)
        cypress->packet_size = le16_to_cpu(bulk_in->wMaxPacketSize);

    cypress->drain_delay = 0;
    usb_set_intfdata(port->port->host, cypress);
    port->port->private_data = cypress;

    return 0;

error:
    kfree(cypress);
    return ret;
}

int cypress_probe(struct usb_serial_port *port)
{
    int ret;
    struct cypress_private *priv;

    /* Check required endpoints */
    if (!port->port.open_count) {
        dev_err(&port->dev, "Endpoints not available\n");
        return -ENODEV;
    }

    /* Allocate private data */
    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    /* Initialize locks and FIFOs */
    spin_lock_init(&priv->lock);
    usb_serial_init_fifo(&priv->read_fifo);
    usb_serial_init_fifo(&priv->write_fifo);

    /* Configure packet format based on interrupt output size */
    if (port->interrupt_out_size > 0)
        priv->packet_size = port->interrupt_out_size;

    /* Handle special device cases */
    if (port->serial->dev->descriptor.idVendor == 0x04b4) {
        if (port->serial->dev->descriptor.idProduct == 0x1000)
            priv->packet_size = 64;
    }

    /* Set read/write intervals */
    if (!port->serial->read_urb_size)
        port->serial->read_urb_size = 0x40;
    if (!port->serial->write_urb_size)
        port->serial->write_urb_size = 0x40;

    /* Associate private data with port */
    usb_set_serial_port_data(port, priv);

    /* Set drain delay */
    port->drain_delay = 0;

    return 0;
}
